class entity;

template<class T> class list
{
public:
    class const_iterator
    {
        void *node;
    public:
        const_iterator();
        const_iterator &operator++();
        bool operator!=(const const_iterator &) const;
        T operator*() const;
    };

    const_iterator begin() const;
    const_iterator end() const;
};

class ai_interface
{
public:
    static const list<ai_interface *> &get_all_ai_interfaces();
    bool is_active() const;
    entity *get_my_entity() const;
};

class game
{
public:
    int get_active_player() const;
};

class world_dynamics_system
{
public:
    entity *get_hero_ptr(int);
};

extern game *g_game_ptr;
extern world_dynamics_system *g_world_ptr;

class trigger
{
    char signaller_and_vtable[12];
    entity *whodunnit;
    char id_next_and_regions[28];
    bool static_regions;
    bool active;
    bool occupied;
    bool use_any_char;

public:
    enum { ENTER, LEAVE };
    virtual bool triggered(entity *);
    virtual void raise_signal(unsigned int) const;
    bool is_active() const { return active; }
    void update();
};

void trigger::update()
{
  if( is_active() )
  {
    // check the hero
    bool hit = triggered( g_world_ptr->get_hero_ptr(g_game_ptr->get_active_player()) );

    if(hit)
      whodunnit = g_world_ptr->get_hero_ptr(g_game_ptr->get_active_player());

    if ( !hit && use_any_char )
    {
      list<ai_interface *>::const_iterator ai = ai_interface::get_all_ai_interfaces().begin();
      list<ai_interface *>::const_iterator ai_end = ai_interface::get_all_ai_interfaces().end();

      // check other characters in the region
      for ( ; !hit && ai!=ai_end; ++ai )
      {
        if((*ai)->is_active())
        {
          hit = triggered( (*ai)->get_my_entity() );

          if(hit)
            whodunnit = (*ai)->get_my_entity();
        }
      }
    }

    // should raise signal?
    if( hit )
    {
      if( !occupied )
        raise_signal( ENTER );
    }
    else
    {
      if( occupied )
        raise_signal( LEAVE );
    }

    occupied = hit;
  }
}
